/**
 * Pure verification rules over a chain snapshot. No I/O: the same snapshot
 * always yields the same verdicts, so tests can feed corrupted inputs and
 * expect MISMATCH. A pass describes the observed state under the stated
 * assumptions — it is not a solvency guarantee (spec §12).
 */

export const ABSOLUTE_LIFETIME_CAP = 25_000_000_000n; // 25,000 USDC-equivalent base units

export interface Snapshot {
  chainId: number;
  blockNumber: bigint;
  blockHash: `0x${string}`;
  blockTimestamp: bigint;
  asset: { symbol: string; decimals: number };
  controller: {
    hullNav: bigint;
    ballastNav: bigint;
    reserveNav: bigint;
    treasuryLiability: bigint;
    lastActive: bigint;
    lifetimeAdmitted: bigint;
    pendingReserved: bigint;
    stageCap: bigint;
    impaired: boolean;
    lossCarry: bigint;
    epoch: bigint;
  };
  custody: { pending: bigint; activeIdle: bigint; tokenBalance: bigint };
  escrow: { totalFunded: bigint; tokenBalance: bigint };
  engine:
    | { present: false }
    | { present: true; simulated: boolean; value: bigint; observedAt: bigint; book?: bigint; pot?: bigint; fundingRateBps?: bigint };
  ballastSupply: bigint;
}

export type Verdict = "PASS" | "MISMATCH" | "SIMULATED" | "INFO";

export interface Check {
  id: string;
  verdict: Verdict;
  summary: string;
  values: Record<string, string>;
}

const s = (x: bigint | number | boolean) => x.toString();

export function evaluate(snap: Snapshot): Check[] {
  const c = snap.controller;
  const out: Check[] = [];

  // Ledger identity: lastActive is the book's A at the last flow/settlement and must equal H+B+R.
  const hbr = c.hullNav + c.ballastNav + c.reserveNav;
  out.push({
    id: "book.identity",
    verdict: c.lastActive === hbr ? "PASS" : "MISMATCH",
    summary: c.lastActive === hbr ? "recorded A equals H + B + R" : "recorded A differs from H + B + R",
    values: { H: s(c.hullNav), B: s(c.ballastNav), R: s(c.reserveNav), recordedA: s(c.lastActive) },
  });

  // Recompute A from custody + engine − treasury liability; the difference is unsettled G.
  const engineValue = snap.engine.present ? snap.engine.value : 0n;
  const gross = snap.custody.activeIdle + engineValue;
  const a = gross > c.treasuryLiability ? gross - c.treasuryLiability : 0n;
  out.push({
    id: "book.unsettled",
    verdict: "INFO",
    summary: "result not yet settled into the tranches (becomes G at the next settlement)",
    values: { recomputedA: s(a), unsettledG: s(a - c.lastActive), treasuryLiability: s(c.treasuryLiability) },
  });

  // Custody backing: the token balance covers both tracked compartments.
  const tracked = snap.custody.pending + snap.custody.activeIdle;
  out.push({
    id: "custody.backing",
    verdict: snap.custody.tokenBalance >= tracked ? "PASS" : "MISMATCH",
    summary:
      snap.custody.tokenBalance >= tracked
        ? "custody holds at least pending + active idle"
        : "custody token balance is below its tracked compartments",
    values: {
      tokenBalance: s(snap.custody.tokenBalance),
      pending: s(snap.custody.pending),
      activeIdle: s(snap.custody.activeIdle),
      quarantined: s(snap.custody.tokenBalance >= tracked ? snap.custody.tokenBalance - tracked : 0n),
    },
  });

  // Claim escrow: every funded pool is backed by tokens.
  out.push({
    id: "escrow.backing",
    verdict: snap.escrow.tokenBalance >= snap.escrow.totalFunded ? "PASS" : "MISMATCH",
    summary:
      snap.escrow.tokenBalance >= snap.escrow.totalFunded
        ? "claim escrow backs every funded claim"
        : "claim escrow holds less than it owes",
    values: { tokenBalance: s(snap.escrow.tokenBalance), totalFunded: s(snap.escrow.totalFunded) },
  });

  // Caps.
  const used = c.lifetimeAdmitted + c.pendingReserved;
  const capsOk = used <= c.stageCap && c.stageCap <= ABSOLUTE_LIFETIME_CAP;
  out.push({
    id: "caps.lifetime",
    verdict: capsOk ? "PASS" : "MISMATCH",
    summary: capsOk ? "admitted + reserved within the stage cap and the V1 ceiling" : "cap exceeded",
    values: { lifetimeAdmitted: s(c.lifetimeAdmitted), pendingReserved: s(c.pendingReserved), stageCap: s(c.stageCap) },
  });

  // Units exist only if capital was admitted.
  const unitsOk = snap.ballastSupply === 0n || c.lifetimeAdmitted > 0n;
  out.push({
    id: "units.backed",
    verdict: unitsOk ? "PASS" : "MISMATCH",
    summary: unitsOk ? "no Ballast units without admitted capital" : "Ballast units exist without admitted capital",
    values: { ballastSupply: s(snap.ballastSupply) },
  });

  // Engine / hedge.
  if (!snap.engine.present) {
    out.push({ id: "engine", verdict: "INFO", summary: "no engine wired", values: {} });
  } else {
    const e = snap.engine;
    out.push({
      id: "engine",
      verdict: e.simulated ? "SIMULATED" : "INFO",
      summary: e.simulated
        ? "engine is SIMULATED (testnet): no spot leg, no short, funding from a seeded pot — not a hedge"
        : "engine is not marked simulated; hedge verification needs venue reads (Session 3, G01–G03)",
      values: {
        value: s(e.value),
        observedAt: s(e.observedAt),
        ...(e.book !== undefined ? { book: s(e.book) } : {}),
        ...(e.pot !== undefined ? { pot: s(e.pot) } : {}),
        ...(e.fundingRateBps !== undefined ? { fundingRateBps: s(e.fundingRateBps) } : {}),
      },
    });
  }

  out.push({
    id: "book.state",
    verdict: "INFO",
    summary: c.impaired ? "book IMPAIRED: fees off, recovery order Hull → Reserve → Ballast" : "book not impaired",
    values: { impaired: s(c.impaired), lossCarry: s(c.lossCarry), epoch: s(c.epoch) },
  });
  return out;
}

export function overall(checks: Check[]): "PASS" | "MISMATCH" {
  return checks.some((c) => c.verdict === "MISMATCH") ? "MISMATCH" : "PASS";
}
